int main(int argc,char**argv){try{req(argc==5,"usage: atlas_control candidate-rows parent-atlas state-table report");auto atlas=read_atlas(argv[2],10);map<uint64_t,unsigned>keys;for(unsigned i=0;i<atlas.size();i++)req(keys.emplace(canonical(atlas[i].r),i).second,"distinct complete parent keys");ifstream in(argv[3]);string line;getline(in,line);vector<map<unsigned,unsigned>>D;vector<unsigned>component;map<unsigned,unsigned>orders;while(getline(in,line)){auto f=split(line,'\t');req(f.size()==6,"state fields");req(stoul(f[0])==D.size(),"state index");component.push_back(stoul(f[1]));map<unsigned,unsigned>d;for(auto pair:split(f[5],',')){auto e=split(pair,':');d[stoul(e[0])]=stoul(e[1]);}unsigned group=d.at(D.size())*atlas[D.size()].g.size();auto it=orders.emplace(component.back(),group);req(it.second||it.first->second==group,"component action orders agree");D.push_back(d);}req(D.size()==atlas.size(),"complete state table");ifstream cand(argv[1]);unsigned N;cand>>N;req(bool(cand)&&N>0&&N<100,"bounded nonrigid candidate set");set<unsigned>matched;uint64_t deficit=0;for(unsigned k=0;k<N;k++){G r(11);for(auto&x:r)cand>>x;req(bool(cand),"candidate row record");valid(r);for(auto row:r)req(pc(row)==5,"candidate regular");auto group=autos(r);req(group.size()>1,"nonrigid candidate full group");map<unsigned,unsigned>d;for(unsigned v=0;v<11;v++){auto it=keys.find(canonical(del(r,v)));req(it!=keys.end(),"candidate every reroot in complete parent atlas");++d[it->second];}unsigned state=d.begin()->first,comp=component[state];req(matched.insert(comp).second,"independent candidates occupy distinct full-atlas components");req(d==D[state],"all candidate deletion multiplicities agree with full atlas");req(group.size()==orders[comp],"independent full automorphism matches full atlas");req(d.size()==orbits(group),"independent actual vertex orbits");deficit+=11-d.size();}set<unsigned>allnonrigid;for(auto x:orders)if(x.second>1)allnonrigid.insert(x.first);req(matched==allnonrigid,"exactly every nonrigid full-atlas component reached");req((atlas.size()+deficit)%11==0,"predicted regular count integer");req((atlas.size()+deficit)/11==orders.size(),"structural deficit recovers trace class count as holdout");ofstream out(argv[4]);out<<"{\"status\":\"PASS\",\"candidate_classes\":"<<N<<",\"parent_classes\":"<<atlas.size()<<",\"regular_classes_holdout\":"<<orders.size()<<",\"nonrigid_pointing_deficit\":"<<deficit<<",\"regular_error_from_deficit\":"<<10*atlas.size()-deficit<<",\"all_candidate_reroots_checked\":"<<11*N<<",\"target_canonicalizations\":0}\n";req(bool(out),"report written");cout<<"PASS exact nonrigid full-atlas holdout\n";}catch(exception&e){cerr<<e.what()<<'\n';return 1;}}
